script:
frappe.ui.form.on('RFQ Comparison Sheet', {
	refresh: function(frm) {
		frm.fields_dict['items'].grid.update_docfield_property('supplier', 'formatter', function(value) {
			return `<div style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:200px;" title="${value || ''}">${value || ''}</div>`;
		});
		['price_score', 'lead_time_score', 'weighted_mark'].forEach(function(fieldname) {
			frm.fields_dict['items'].grid.update_docfield_property(fieldname, 'formatter', function(value) {
				if (value === null || value === undefined) return '';
				return parseFloat(value).toFixed(2);
			});
		});

		setTimeout(function() {
			frm.fields_dict['items'].grid.refresh();
		}, 300);

	}
});

frappe.ui.form.on('Request for Quotation', {
	refresh: function(frm) {
		if (frm.doc.workflow_state === 'Approved') {
			frm.add_custom_button('Generate Comparison Sheet', function() {
				frappe.call({
					method: 'proc_app.api.rfq.generate_comparison_sheet',
					args: { rfq_name: frm.doc.name },
					freeze: true,
					freeze_message: __('Generating comparison sheet...'),
					callback: function(r) {
						if (r.message) {
							frappe.set_route('Form', 'RFQ Comparison Sheet', r.message);
						}
					}
				});
			}, __('Create'));

			frappe.db.get_value('RFQ Comparison Sheet', {request_for_quotation: frm.doc.name}, 'name').then(function(r) {
				if (r.message && r.message.name) {
					frappe.call({
						method: 'proc_portal.api.rfqs.get_purchase_orders_for_rfq',
						args: { rfq_name: frm.doc.name },
						callback: function(po_r) {
							var existing_pos = po_r.message || [];
							if (existing_pos.length) {
								frm.add_custom_button('View Purchase Orders', function() {
									frappe.set_route('List', 'Purchase Order', {
										name: ['in', existing_pos.map(function(po) { return po.name; })]
									});
								}, __('Create'));
							} else {
								frm.add_custom_button('Generate Purchase Orders', function() {
									frappe.call({
										method: 'proc_app.api.rfq.generate_purchase_orders_from_comparison',
										args: { rfq_name: frm.doc.name },
										freeze: true,
										freeze_message: __('Generating purchase orders...'),
										callback: function(r) {
											if (r.message) {
												frappe.msgprint(__('Created: ') + r.message.join(', '));
											}
										}
									});
								}, __('Create'));
							}
						}
					});
				}
			});
		}
	}
});

frappe.ui.form.on('Supplier Quotation Item', {
	lead_time_days: function(frm, cdt, cdn) {
		let row = locals[cdt][cdn];
		if (row.lead_time_days) {
			let base_date = frm.doc.transaction_date || frappe.datetime.get_today();
			row.expected_delivery_date = frappe.datetime.add_days(base_date, row.lead_time_days);
			frm.refresh_field('items');
		}
	}
});

frappe.ui.form.on('Supplier ASN', {
	refresh: function(frm) {
		if (frm.doc.docstatus !== 2 && frm.doc.status !== 'Cancelled') {
			frm.add_custom_button('Purchase Receipt', function() {
				frappe.model.open_mapped_doc({
					method: 'proc_app.api.asn.make_purchase_receipt_from_asn',
					frm: frm,
				});
			}, __('Create'));
		}
	}
});

frappe.ui.form.on('Contract', {
	refresh: function(frm) {
		if (frm.doc.__islocal) return;

		// Consumption indicator - only meaningful when a value is set
		if (frm.doc.contract_value) {
			frappe.call({
				method: 'proc_portal.api.contracts.get_contract_consumption',
				args: { contract_name: frm.doc.name },
				callback: function(r) {
					if (!r.message) return;
					const d = r.message;
					const color = d.over_committed ? 'red' : (d.consumed_pct >= 80 ? 'orange' : 'blue');
					frm.dashboard.add_indicator(
						__('Consumed: {0}% ({1} of {2})', [d.consumed_pct, format_currency(d.consumed), format_currency(d.contract_value)]),
						color
					);
					if (d.remaining) {
						frm.dashboard.add_indicator(__('Remaining: {0}', [format_currency(d.remaining)]), 'green');
					}
				}
			});
		}

		// Renew - gated identically to the portal (Approved only)
		if (frm.doc.workflow_state === 'Approved') {
			frm.add_custom_button(__('Renew Contract'), function() {
				const dialog = new frappe.ui.Dialog({
					title: __('Renew Contract'),
					fields: [
						{fieldname: 'new_start_date', label: __('New Start Date'), fieldtype: 'Date', reqd: 1},
						{fieldname: 'new_end_date', label: __('New End Date'), fieldtype: 'Date', reqd: 1},
						{fieldname: 'new_value', label: __('New Contract Value'), fieldtype: 'Currency', default: frm.doc.contract_value},
					],
					primary_action_label: __('Renew'),
					primary_action: function(values) {
						frappe.call({
							method: 'proc_portal.api.contracts.renew_contract',
							args: {
								contract_name: frm.doc.name,
								new_start_date: values.new_start_date,
								new_end_date: values.new_end_date,
								new_value: values.new_value,
							},
							freeze: true,
							freeze_message: __('Creating renewal...'),
							callback: function(r) {
								if (r.message && r.message.name) {
									dialog.hide();
									frappe.set_route('Form', 'Contract', r.message.name);
								}
							}
						});
					}
				});
				dialog.show();
			}, __('Actions'));
		}

		// Renewal lineage - show where this contract came from
		if (frm.doc.renewed_from) {
			frm.dashboard.add_comment(__('Renewed from {0}', [
				`<a href="/app/contract/${frm.doc.renewed_from}">${frm.doc.renewed_from}</a>`
			]), 'blue', true);
		}
	}
});
